def create_api_redirect_url(base_url_api, api_endpoint, opts=None):
    if not any(base_url_api.startswith(domain) for domain in APPROVED_API_DOMAINS):
        raise ValueError("URL domain is not allowed")
    if api_endpoint not in ALLOWED_ENDPOINTS:
        raise ValueError("Endpoint is not allowed")

    if opts:
        params = urllib.parse.urlencode(opts)
        base_url_api += f"?{params}"

    url_parts = urllib.parse.urlparse(base_url_api)
    domain = url_parts.netloc
    path = url_parts.path + api_endpoint

    if not any(path.startswith(allowed_endpoint) for allowed_endpoint in ALLOWED_ENDPOINTS):
        raise ValueError("Endpoint is not allowed")

    return f"{url_parts.scheme}://{domain}{path}"

