def restricted_run_code(run_code):

    class RestrictedCodeVisitor(ast.NodeVisitor):
        def visit_Import(self, node):
            raise ValueError("Import operations are not allowed")

        def visit_ImportFrom(self, node):
            raise ValueError("Import operations are not allowed")

        def visit_Call(self, node):
            if isinstance(node.func, ast.Name):
                if node.func.id in ["exec", "eval", "compile"]:
                    raise ValueError("Eval, exec, and compile functions are not allowed")

        def visit_FunctionDef(self, node):
            if node.name in ["eval", "exec", "compile"]:
                raise ValueError("Function names eval, exec, and compile are not allowed")

        def visit_Assign(self, node):
            if any(isinstance(target, ast.Name) and target.id in ["__builtins__", "exec", "eval", "compile"] for target in node.targets):
                raise ValueError("Assignment to __builtins__, exec, eval, and compile is not allowed")

        def visit_Expr(self, node):
            if isinstance(node.value, ast.Call):
                self.visit_Call(node.value)

    try:
        tree = ast.parse(run_code)
        RestrictedCodeVisitor().visit(tree)
        exec(compile(tree, filename="<ast>", mode="exec"))
        return "Code executed successfully"
    except ValueError as e:
        return str(e)
    except Exception as e:
        return str(e)

