        for condition in where_conditions:
            field, operator_str, value = condition.strip().split()
            if operator_str == '>':
                data = [item for item in data if item[field] > value]
            elif operator_str == '<':
                data = [item for item in data if item[field] < value]
            else:
                raise ValueError("Unsupported operator")

    # Select fields
    if select_fields:
        data = [{field: item[field] for field in select_fields} for item in data]

    # Order data
    if order_by:
        data = sorted(data, key=lambda x: x[order_by])

    return data

